import{_ as e,c as r,o as h,af as p}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"卷二（谦、豫、随、蛊）","description":"伊川易传 - 卷二（谦、豫、随、蛊）","frontmatter":{"title":"卷二（谦、豫、随、蛊）","description":"伊川易传 - 卷二（谦、豫、随、蛊）"},"headers":[],"relativePath":"zh/classics/yichuan/003.md","filePath":"zh/classics/yichuan/003.md"}'),i={name:"zh/classics/yichuan/003.md"};function l(n,a,d,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[p('<h1 id="卷二-谦、豫、随、蛊" tabindex="-1">卷二（谦、豫、随、蛊） <a class="header-anchor" href="#卷二-谦、豫、随、蛊" aria-label="Permalink to “卷二（谦、豫、随、蛊）”">​</a></h1><p>谦卦</p><p>导读</p><p>《谦》，《序卦》：“有大者不可以盈，故受之以谦。”其有既大，不可至于盈满，必在谦损，故大有之后，受之以谦也。为卦，坤上艮下，地中有山也。地体卑下，山，高大之物，而居地之下，谦之象也。以崇高之德，而处卑之下，谦之义也。</p><h3 id="卦辞-亨-君子有终。" tabindex="-1">卦辞：亨，君子有终。 <a class="header-anchor" href="#卦辞-亨-君子有终。" aria-label="Permalink to “卦辞：亨，君子有终。”">​</a></h3><p>谦有亨之道也。有其德而不居，谓之谦。人以谦巽自处，何往而不亨乎。君子有终，君子志存乎谦巽，达理，故乐天而不竞，内充，故退让而不矜，安履乎谦，终身不易，自卑而人益尊之，自晦而德益光显，此所谓君子有终也。在小人则有欲必竞，有德必伐，虽使勉慕于谦，亦不能安行而固守，不能有终也。</p><h3 id="《彖》曰-谦亨-天道下济而光明-地道卑而上行。天道亏盈而益谦-地道变盈而流谦-鬼神害盈而福谦-人道恶盈而好谦。谦尊而光-卑而不可逾-君子之终也。" tabindex="-1">《彖》曰：谦亨，天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。谦尊而光，卑而不可逾，君子之终也。 <a class="header-anchor" href="#《彖》曰-谦亨-天道下济而光明-地道卑而上行。天道亏盈而益谦-地道变盈而流谦-鬼神害盈而福谦-人道恶盈而好谦。谦尊而光-卑而不可逾-君子之终也。" aria-label="Permalink to “《彖》曰：谦亨，天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。谦尊而光，卑而不可逾，君子之终也。”">​</a></h3><p>济当为际。此明谦而能亨之义。天之道，以其气下际，故能化育万物，其道光明。下际谓下交也。地之道，以其处卑，所以其气上行，交于天，皆以卑降而亨也。</p><p>以天行而言，盈者则亏，谦者则益，日月阴阳是也。</p><p>以地势而言，盈满者倾变而反陷，卑下者流注而益增也。</p><p>鬼神谓造化之迹。盈满者祸害之，谦损者福祐之，凡过而损，不足而益者，皆是也。</p><p>人情疾恶于盈满，而好与于谦巽也。谦者人之至德，故圣人详言，所以戒盈而劝谦也。</p><p>谦为卑巽也，而其道尊大而光显。自处虽卑屈，而其德实高不可加尚，是不可逾也。君子至诚于谦，恒而不变，有终也，故尊光。</p><h3 id="象曰-地中有山-谦-君子以裒多益寡-称物平施。" tabindex="-1">象曰：地中有山，谦，君子以裒多益寡，称物平施。 <a class="header-anchor" href="#象曰-地中有山-谦-君子以裒多益寡-称物平施。" aria-label="Permalink to “象曰：地中有山，谦，君子以裒多益寡，称物平施。”">​</a></h3><p>地体卑下，山之高大而在地中，外卑下而内蕴高大之象，故为谦也。不云山在地中，而曰地中有山，言卑下之中蕴其崇高也。若言崇高蕴于卑下之中，则文理不顺。诸象皆然，观文可见。君子以裒多益寡，称物平施，君子观谦之象，山而在地下，是高者下之，卑者上之，见抑高举下、损过益不及之义；以施于事，则裒取多者，增益寡者，称物之多寡以均其施与，使得其平也。</p><h3 id="初六-谦谦君子-用涉大川-吉。-象曰-谦谦君子-卑以自牧也。" tabindex="-1">初六，谦谦君子，用涉大川，吉。 象曰：谦谦君子，卑以自牧也。 <a class="header-anchor" href="#初六-谦谦君子-用涉大川-吉。-象曰-谦谦君子-卑以自牧也。" aria-label="Permalink to “初六，谦谦君子，用涉大川，吉。 象曰：谦谦君子，卑以自牧也。”">​</a></h3><p>初六以柔顺处谦，又居一卦之下，为自处卑下之至，谦而又谦也，故曰谦谦。能如是者，君子也。自处至谦，众所共与也，虽用涉险难，亦无患害，况居平易乎？何所不吉也？初处谦而以柔居下，得无过于谦乎？曰：柔居下，乃其常也，但见其谦之至，故为谦谦，未见其失也。</p><p>谦谦，谦之至也。谓君子以谦卑之道自牧也。自牧，自处也。《诗》云：“自牧归荑。”</p><h3 id="六二-鸣谦-贞吉。-象曰-鸣谦贞吉-中心得也。" tabindex="-1">六二，鸣谦，贞吉。 象曰：鸣谦贞吉，中心得也。 <a class="header-anchor" href="#六二-鸣谦-贞吉。-象曰-鸣谦贞吉-中心得也。" aria-label="Permalink to “六二，鸣谦，贞吉。 象曰：鸣谦贞吉，中心得也。”">​</a></h3><p>二以柔顺居中，是为谦德积于中。谦德充积于中，故发于外，见于声音颜色，故曰鸣谦。居中得正，有中正之德也，故云贞吉。凡贞吉，有为贞且吉者，有为得贞则吉者，六二之贞吉，所自有也。</p><p>二之谦德，由至诚积于中，所以发于声音，中心所自得也，非勉为之也。</p><h3 id="九三-劳谦-君子有终-吉。-象曰-劳谦君子-万民服也。" tabindex="-1">九三，劳谦，君子有终，吉。 象曰：劳谦君子，万民服也。 <a class="header-anchor" href="#九三-劳谦-君子有终-吉。-象曰-劳谦君子-万民服也。" aria-label="Permalink to “九三，劳谦，君子有终，吉。 象曰：劳谦君子，万民服也。”">​</a></h3><p>三以阳刚之德而居下体，为众阴所宗，履得其位，为下之上，是上为君所任，下为众所从，有功劳而持谦德者也，故曰劳谦。古之人有当之者，周公是也。身当天下之大任，上奉幼弱之主，谦恭自牧，夔夔如畏然，可谓有劳而能谦矣。既能劳谦，又须君子行之有终，则吉。夫乐高喜胜，人之常情。平时能谦，固已鲜矣，况有功劳可尊乎？虽使知谦之善，勉而为之，若矜负之心不忘，则不能常久，欲其有终，不可得也。唯君子安履谦顺，乃其常行，故久而不变，乃所谓有终，有终则吉也。九三以刚居正，能终者也。此爻之德最盛，故象辞特重。</p><p>能劳谦之君子，万民所尊服也。《系辞》云：“劳而不伐，有功而不德，厚之至也。语以其功下人者也。德言盛，礼言恭。谦也者，致恭以存其位者也。”有劳而不自矜伐，有功而不自以为德，是其德弘厚之至也。言以其功劳而自谦，以下于人也。德言盛，礼言恭。以其德言之，则至盛，以其自处之礼言之，则至恭，此所谓谦也。夫谦也者，谓致恭以存其位者也。存，守也。致其恭巽以守其位，故高而不危，满而不溢，是以能终吉也。夫君子履谦，乃其常行，非为保其位而为之也。而言存其位者，盖能致恭所以能存其位，言谦之道如此。如言为善有令名，君子岂为令名而为善也哉？亦言其令名者，为善之故也。</p><h3 id="六四-无不利-挥谦。-象曰-无不利-谦-不违则也。" tabindex="-1">六四，无不利，挥谦。 象曰：无不利?谦，不违则也。 <a class="header-anchor" href="#六四-无不利-挥谦。-象曰-无不利-谦-不违则也。" aria-label="Permalink to “六四，无不利，挥谦。 象曰：无不利?谦，不违则也。”">​</a></h3><p>四居上体，切近君位，六五之君又以谦柔自处，九三又有大功德，为上所任、众所宗，而己居其上，当恭畏以奉谦德之君，卑巽以让劳谦之臣，动作施为，无所不利于?谦也。?，施布之象，如人手之?也。动息进退，必施其谦，盖居多惧之地，又在贤臣之上故也。</p><p>凡人之谦，有所宜施，不可过其宜也。如六五或用侵伐是也。唯四以处近君之地，据劳臣之上，故凡所动作，靡不利于施谦，如是然后中于法则，故曰不违则也，谓得其宜也。</p><h3 id="六五-不富以其邻-利用侵伐-无不利。-象曰-利用侵伐-征不服也。" tabindex="-1">六五，不富以其邻，利用侵伐，无不利。 象曰：利用侵伐，征不服也。 <a class="header-anchor" href="#六五-不富以其邻-利用侵伐-无不利。-象曰-利用侵伐-征不服也。" aria-label="Permalink to “六五，不富以其邻，利用侵伐，无不利。 象曰：利用侵伐，征不服也。”">​</a></h3><p>富者众之所归，唯财为能聚人。五以君位之尊，而执谦顺以接于下，众所归也，故不富而能有其邻也。邻，近也。不富而得人之亲也，为人君而持谦顺，天下所归心也。然君道不可专尚谦柔，必须威武相济，然后能怀服天下，故利用行侵伐也。威德并著，然后尽君道之宜，而无所不利也。盖五之谦柔，当防于过，故发此义。</p><p>征其文德谦巽所不能服者也。文德所不能服，而不用威武，何以平治天下？非人君之中道，谦之过也。</p><h3 id="上六-鸣谦-利用行师-征邑国。-象曰-鸣谦-志未得也-可用行师征邑国也。" tabindex="-1">上六，鸣谦，利用行师，征邑国。 象曰：鸣谦，志未得也，可用行师征邑国也。 <a class="header-anchor" href="#上六-鸣谦-利用行师-征邑国。-象曰-鸣谦-志未得也-可用行师征邑国也。" aria-label="Permalink to “上六，鸣谦，利用行师，征邑国。 象曰：鸣谦，志未得也，可用行师征邑国也。”">​</a></h3><p>六以柔处柔，顺之极，又处谦之极，极乎谦者也。以极谦而反居高，未得遂其谦之志，故至发于声音；又柔处谦之极，亦必见于声色，故曰鸣谦。虽居无位之地，非任天下之事，然人之行己，必须刚柔相济。上，谦之极也，至于大甚，则反为过矣。故利在以刚武自治。邑国，己之私有。行师，谓用刚武。征邑国，谓自治其私。</p><p>谦极而居上，欲谦之志未得，故不胜其切，至于鸣也。虽不当位，谦既过极，宜以刚武自治其私，故云利用行师征邑国也。</p><p>豫卦</p><p>导读</p><p>《豫》，《序卦》：“有大而能谦必豫，故受之以豫。”承二卦之义而为次也，有既大而能谦，则有豫乐也。豫者，安和悦乐之义。为卦，震上坤下，顺动之象。动而和顺，是以豫也。九四为动之主，上下群阴所共应也，坤又承之以顺，是以动而上下顺应，故为和豫之义。以二象言之，雷出于地上。阳始潜闭于地中，及其动而出地，奋发其声，通畅和豫，故为豫也。</p><h3 id="卦辞-利建侯行师。" tabindex="-1">卦辞：利建侯行师。 <a class="header-anchor" href="#卦辞-利建侯行师。" aria-label="Permalink to “卦辞：利建侯行师。”">​</a></h3><p>豫，顺而动也。豫之义，所利在于建侯行师。夫建侯树屏，所以共安天下，诸侯和顺则万民悦服，兵师之兴，众心和悦，则顺从而有功，故悦豫之道，利于建侯行师也。又上动而下顺，诸侯从王，师众顺令之象。君万邦，聚大众，非和悦不能使之服从也。</p><h3 id="《彖》曰-豫-刚应而志行-顺以动-豫。豫顺以动-故天地如之-而况建侯行师乎-天地以顺动-故日月不过而四时不忒-圣人以顺动-则刑罚清而民服。豫之时义大矣哉" tabindex="-1">《彖》曰：豫，刚应而志行，顺以动，豫。豫顺以动，故天地如之，而况建侯行师乎？天地以顺动，故日月不过而四时不忒；圣人以顺动，则刑罚清而民服。豫之时义大矣哉！ <a class="header-anchor" href="#《彖》曰-豫-刚应而志行-顺以动-豫。豫顺以动-故天地如之-而况建侯行师乎-天地以顺动-故日月不过而四时不忒-圣人以顺动-则刑罚清而民服。豫之时义大矣哉" aria-label="Permalink to “《彖》曰：豫，刚应而志行，顺以动，豫。豫顺以动，故天地如之，而况建侯行师乎？天地以顺动，故日月不过而四时不忒；圣人以顺动，则刑罚清而民服。豫之时义大矣哉！”">​</a></h3><p>刚应，谓四为群阴所应，刚得众应也。志行，谓阳志上行，动而上下顺从，其志得行也。顺以动豫，震动而坤顺为动而顺理，顺理而动又为动而众顺，所以豫也。</p><p>以豫顺而动，则天地如之而弗违，况建侯行师，岂有不顺乎？天地之道，万物之理，唯至顺而已。大人所以先天后天而不违者，亦顺乎理而已。</p><p>复详言顺动之道。天地之运，以其顺动，所以日月之度不过差，四时之行不愆忒；圣人以顺动，故经正而民兴于善，刑罚清简而万民服也。</p><p>既言豫顺之道矣，然其旨味渊永，言尽而意有余也，故复赞之云：“豫之时义大矣哉！”欲人研味其理，优柔涵泳而识之也。时义，谓豫之时义。诸卦之时与义用大者，皆赞其大矣哉，《豫》以下十一卦是也。《豫》、《遁》、《后》、《旅》言时义，《坎》、《暌》、《蹇》言时用，《颐》、《大过》、《解》、《革》言时，各以其大者也。</p><h3 id="象曰-雷出地奋-豫-先王以作乐崇德-殷荐之上帝-以配祖考。" tabindex="-1">象曰：雷出地奋，豫，先王以作乐崇德，殷荐之上帝，以配祖考。 <a class="header-anchor" href="#象曰-雷出地奋-豫-先王以作乐崇德-殷荐之上帝-以配祖考。" aria-label="Permalink to “象曰：雷出地奋，豫，先王以作乐崇德，殷荐之上帝，以配祖考。”">​</a></h3><p>雷者，阳气奋发，阴阳相薄而成声也。阳始潜闭地中，及其动，则出地奋震也。始闭郁，及奋发则通畅和豫，故为豫也。坤顺震发，和顺积中而发于声，乐之象也。先王观雷出地而奋，和畅发于声之象，作声乐以褒崇功德，其殷盛至于荐之上帝，推配之以祖考。殷，盛也。礼有殷奠，谓盛也。荐上帝，配祖考，盛之至也。</p><h3 id="初六-鸣豫-凶。-象曰-初六鸣豫-志穷凶也。" tabindex="-1">初六，鸣豫，凶。 象曰：初六鸣豫，志穷凶也。 <a class="header-anchor" href="#初六-鸣豫-凶。-象曰-初六鸣豫-志穷凶也。" aria-label="Permalink to “初六，鸣豫，凶。 象曰：初六鸣豫，志穷凶也。”">​</a></h3><p>初六以阴柔居下，四豫之主也，而应之，是不中正之小人处豫，而为上所宠，其志意满极，不胜其豫，至发于声音，轻浅如是，必至于凶也。鸣，发于声也。</p><p>云初六，谓其以阴柔处下，而志意穷极，不胜其豫，至于鸣也，必骄肆而致凶矣。</p><h3 id="六二-介于石-不终日-贞吉。-象曰-不终日贞吉-以中正也。" tabindex="-1">六二，介于石，不终日，贞吉。 象曰：不终日贞吉，以中正也。 <a class="header-anchor" href="#六二-介于石-不终日-贞吉。-象曰-不终日贞吉-以中正也。" aria-label="Permalink to “六二，介于石，不终日，贞吉。 象曰：不终日贞吉，以中正也。”">​</a></h3><p>逸豫之道，放则失正，故豫之诸爻，多不得正，才与时合也。唯六二一爻处中正，又无应，为自守之象。当豫之时，独能以中正自守，可谓特立之操，是其节介如石之坚也。介于石，其介如石也。人之于豫乐，心悦之，故迟迟遂至于耽恋不能已也。二以中正自守，其介如石，其去之速，不俟终日，故贞正而吉也。处豫不可安且久也，久则溺矣。如二，可谓见几而作者也。夫子因二之见几，而极言知几之道，曰：“知几其神乎！君子上交不谄，下交不渎，其知几乎！几者动之微、吉之先见者也。君子见几而作，不俟终日。《易》曰：‘介于石，不终日，贞吉。’介如石焉，宁用终日，断可识矣。君子知微知彰，知柔知刚，万夫之望。”夫见事之几微者，其神妙矣乎！君子上交不至于谄，下交不至于渎者，盖知几也。不知几，则至于过而不已。交于上以恭巽，故过则为谄；交于下以和易，故过则为渎。君子见于几微，故不至于过也。所谓几者，始动之微也，吉凶之端可先见而未著者也。独言吉者，见之于先，岂复至有凶也？君子明哲，见事之几微，故能其介如石，其守既坚，则不惑而明，见几而动，岂俟终日也？断，别也。其判别可见矣。微与彰，柔与刚，相对者也。君子见微则知彰矣，见柔则知刚矣，知几如是，众所仰也，故赞之曰“万夫之望”。</p><p>能不终日而贞且吉者，以有中正之德也。中正故其守坚，而能辨之早，去之速。爻言六二处豫之道，为教之意深矣。</p><h3 id="六三-盱豫-悔-迟有悔。-象曰-盱豫有悔-位不当也。" tabindex="-1">六三，盱豫，悔，迟有悔。 象曰：盱豫有悔，位不当也。 <a class="header-anchor" href="#六三-盱豫-悔-迟有悔。-象曰-盱豫有悔-位不当也。" aria-label="Permalink to “六三，盱豫，悔，迟有悔。 象曰：盱豫有悔，位不当也。”">​</a></h3><p>六三阴而居阳，不中不正之人也。以不中正而处豫，动皆有悔。盱，上视也。上瞻望于四，则以不中正不为四所取，故有悔也。四，豫之主，与之切近，苟迟迟而不前，则见弃绝，亦有悔也。盖处身不正，进退皆有悔吝。当如之何？在正身而已。君子处己有道，以礼制心，虽处豫时，不失中正，故无悔也。</p><p>自处不当，失中正也，是以进退有悔。</p><h3 id="九四-由豫-大有得-勿疑-朋盍簪。-象曰-由豫-大有得-志大行也。" tabindex="-1">九四，由豫，大有得，勿疑，朋盍簪。 象曰：由豫，大有得，志大行也。 <a class="header-anchor" href="#九四-由豫-大有得-勿疑-朋盍簪。-象曰-由豫-大有得-志大行也。" aria-label="Permalink to “九四，由豫，大有得，勿疑，朋盍簪。 象曰：由豫，大有得，志大行也。”">​</a></h3><p>豫之所以为豫者，由九四也，为动之主，动而众阴悦顺，为豫之义。四，大臣之位，六五之君顺从之，以阳刚而任上之事，豫之所由也，故云由豫。大有得，言得大行其志，以致天下之豫也。勿疑，朋盍簪：四居大臣之位，承柔弱之君，而当天下之任，危疑之地也，独当上之倚任，而下无同德之助，所以疑也。唯当尽其至诚，勿有疑虑，则朋类自当盍聚。夫欲上下之信，唯至诚而已。苟尽其至诚，则何患乎其无助也？簪，聚也。簪之名簪，取聚发也。或曰：卦唯一阳，安得同德之助？曰：居上位而至诚求助，理必得之。《后》之九五曰有陨自天是也。四以阳刚，迫近君位，而专主乎豫，圣人宜为之戒，而不然者，豫和顺之道也，由和顺之道，不失为臣之正也。如此而专主于豫，乃是任天下之事而致时于豫者也，故唯戒以至诚勿疑。</p><p>由己而致天下于乐豫，故为大有得，谓其志得大行也。</p><h3 id="六五-贞疾-恒不死。-象曰-六五贞疾-乘刚也-恒不死-中未亡也。" tabindex="-1">六五，贞疾，恒不死。 象曰：六五贞疾，乘刚也；恒不死，中未亡也。 <a class="header-anchor" href="#六五-贞疾-恒不死。-象曰-六五贞疾-乘刚也-恒不死-中未亡也。" aria-label="Permalink to “六五，贞疾，恒不死。 象曰：六五贞疾，乘刚也；恒不死，中未亡也。”">​</a></h3><p>六五以阴柔居君位，当豫之时，沉溺于豫，不能自立者也。权之所主，众之所归，皆在于四。四之阳刚得众，非耽惑柔弱之君所能制也，乃柔弱不能自立之君，受制于专权之臣也，居得君位贞也，受制于下有疾苦也。六居尊位，权虽失而位未亡也，故云贞疾恒不死，言贞而有疾，常疾而不死，如汉、魏末世之君也。人君致危亡之道非一，而以豫为多。在四不言失正，而于五乃见其强逼者，四本无失，故于四言大臣任天下之事之义，于五则言柔弱居尊，不能自立，威权去己之义，各据爻以取义，故不同也。若五不失君道，而四主于豫，乃是任得其人安享其功，如太甲、成王也。《蒙》亦以阴居尊位，二以阳为蒙之主，然彼吉而此疾者，时不同也。童蒙而资之于人，宜也；耽豫而失之于人，危亡之道也。故蒙相应，则倚任者也；《豫》相逼，则失权者也。又上下之心专归于四也。</p><p>贞而疾，由乘刚为刚所逼也。恒不死，中之尊位未亡也。</p><h3 id="上六-冥豫成-有渝无咎。-象曰-冥豫在上-何可长也" tabindex="-1">上六，冥豫成，有渝无咎。 象曰：冥豫在上，何可长也？ <a class="header-anchor" href="#上六-冥豫成-有渝无咎。-象曰-冥豫在上-何可长也" aria-label="Permalink to “上六，冥豫成，有渝无咎。 象曰：冥豫在上，何可长也？”">​</a></h3><p>上六阴柔，非有中正之德，以阴居上，不正也。而当豫极之时，以君子居斯时，亦当戒惧，况阴柔乎？乃耽肆于豫，昏迷不知反者也。在豫之终，故为昏冥已成也。若能有渝变，则可以无咎矣。在豫之终，有变之义。人之失，苟能自变，皆可以无咎，故冥豫虽已成，能变则善也。圣人发此义，所以劝迁善也，故更不言冥之凶，专言渝之无咎。</p><p>昏冥于豫，至于终极，灾咎行及矣。其可长然乎？当速渝也。</p><p>随卦</p><p>导读</p><p>《随》，《序卦》：“豫必有随，故受之以随。”夫悦豫之道，物所随也，随所以次豫也。为卦，兑上震下，兑为说，震为动，说而动，动而说，皆随之义。女随人者也，以少女从长男，随之义也。又震为雷，兑为泽，雷震于泽中，泽随而动，随之象也。又以卦变言之，乾之上来居坤之下，坤之初往居乾之上，阳来下于阴也。以阳下阴，阴必说随，为随之义。凡成卦，既取二体之义，又有取爻义者，复有更取卦变之义者，如随之取义，尤为详备。</p><h3 id="卦辞-元-亨-利-贞-无咎。" tabindex="-1">卦辞：元，亨，利，贞，无咎。 <a class="header-anchor" href="#卦辞-元-亨-利-贞-无咎。" aria-label="Permalink to “卦辞：元，亨，利，贞，无咎。”">​</a></h3><p>随之道，可以致大亨也。君子之道，为众所随，与己随于人，及临事择所随，皆随也。随得其道，则可以致大亨也。凡人君之从善，臣下之奉命，学者之徙义，临事而从长，皆随也。随之道，利在于贞正，随得其正，然后能大亨而无咎。失其正则有咎矣，岂能亨乎？</p><h3 id="《彖》曰-随-刚来而下柔-动而说-随。大亨贞-无咎-而天下随时。随时之义大矣哉" tabindex="-1">《彖》曰：随，刚来而下柔，动而说，随。大亨贞，无咎，而天下随时。随时之义大矣哉！ <a class="header-anchor" href="#《彖》曰-随-刚来而下柔-动而说-随。大亨贞-无咎-而天下随时。随时之义大矣哉" aria-label="Permalink to “《彖》曰：随，刚来而下柔，动而说，随。大亨贞，无咎，而天下随时。随时之义大矣哉！”">​</a></h3><p>卦所以为随，以刚来而下柔，动而说也，谓乾之上九来居坤之下，坤之初六往居乾之上，以阳刚来下于阴柔，是以上下下，以贵下贱，能如是，物之所说随也。又下动而上说，动而可说也，所以随也。如是则可大亨而得正，能大亨而得正，则为无咎。不能亨，不得正，则非可随之道，岂能使天下随之乎？天下所随者时也，故云“天下随时”。</p><p>君子之道，随时而动，从宜适变，不可为典要，非造道之深，知几能权者，不能与于此也。故赞之曰“随时之义大矣哉！”凡赞之者，欲人知其义之大，玩而识之也。此赞随时之义大，与《豫》等诸卦不同，诸卦时与义是两事。</p><h3 id="象曰-泽中有雷-随-君子以向晦入宴息。" tabindex="-1">象曰：泽中有雷，随，君子以向晦入宴息。 <a class="header-anchor" href="#象曰-泽中有雷-随-君子以向晦入宴息。" aria-label="Permalink to “象曰：泽中有雷，随，君子以向晦入宴息。”">​</a></h3><p>雷震于泽中，泽随震而动，为随之象。君子观象，以随时而动。随时之宜，万事皆然，取其最明且近者言之。君子以向晦入宴息：君子昼则自强不息，及向昏晦，则入居于内，宴息以安其身，起居随时，适其宜也。《礼》：君子昼不居内，夜不居外，随时之道也。</p><h3 id="初九-官有渝-贞吉-出门交有功。-象曰-官有渝-从正吉也。出门交有功-不失也。" tabindex="-1">初九，官有渝，贞吉，出门交有功。 象曰：官有渝，从正吉也。出门交有功，不失也。 <a class="header-anchor" href="#初九-官有渝-贞吉-出门交有功。-象曰-官有渝-从正吉也。出门交有功-不失也。" aria-label="Permalink to “初九，官有渝，贞吉，出门交有功。 象曰：官有渝，从正吉也。出门交有功，不失也。”">​</a></h3><p>九居随时而震体且动之主，有所随者也。官，主守也。既有所随，是其所主守有变易也，故曰官有渝，贞吉，所随得正则吉也。有渝而不得正，乃过动也。出门交有功：人心所从，多所亲爱者也。常人之情，爱之则见其是，恶之则见其非，故妻孥之言虽失而多从，所憎之言虽善为恶也。苟以亲爱而随之，则是私情所与，岂合正理，故出门而交则有功也。出门谓非私昵，交不以私，故其随当而有功。</p><p>既有随而变，必所从得正则吉也。所从不正，则有悔吝。</p><p>出门而交，非牵于私，其交必正矣，正则无失而有功。</p><h3 id="六二-系小子-失丈夫。-象曰-系小子-弗兼与也。" tabindex="-1">六二，系小子，失丈夫。 象曰：系小子，弗兼与也。 <a class="header-anchor" href="#六二-系小子-失丈夫。-象曰-系小子-弗兼与也。" aria-label="Permalink to “六二，系小子，失丈夫。 象曰：系小子，弗兼与也。”">​</a></h3><p>二应五而比初，随先于近柔，不能固守，故为之戒云：若系小子，则失丈夫也。初阳在下，小子也；五正应在上，丈夫也。二若志系于初，则失九五之正应，是失丈夫也。系小子而失丈夫，舍正应而从不正，其咎大矣。二有中正之德，非必至如是也，在随之时，当为之戒也。</p><p>人之所随，得正则远邪，从非则失是，无两从之理。二苟系初，则失五矣，弗能兼与也。所以戒人从正当专一也。</p><h3 id="六三-系丈夫-失小子-随有求得-利居贞。-象曰-系丈夫-志舍下也。" tabindex="-1">六三，系丈夫，失小子，随有求得，利居贞。 象曰：系丈夫，志舍下也。 <a class="header-anchor" href="#六三-系丈夫-失小子-随有求得-利居贞。-象曰-系丈夫-志舍下也。" aria-label="Permalink to “六三，系丈夫，失小子，随有求得，利居贞。 象曰：系丈夫，志舍下也。”">​</a></h3><p>丈夫九四也，小子初也。阳之在上者丈夫也，居下者小子也。三虽与初同体，而切近于四，故系于四也。大抵阴柔不能自立，常亲系于所近者。上系于四，故下失于初，舍初从上，得随之宜也，上随则善也。如昏之随明，事之从善，上随也。背是从非，舍明逐暗，下随也。四亦无应，无随之者也，近得三之随，必与之亲善。故三之随四，有求必得也。人之随于上，而上与之，是得所求也。又凡所求者可得也。虽然，固不可非理枉道以随于上，苟取爱说以遂所求。如此，乃小人邪谄趋利之为也，故云利居贞。自处于正，则所谓有求而必得者，乃正事君子之随也。</p><p>既随于上，则是其志舍下而不从也。舍下而从上，舍卑而从高也，于随为善矣。</p><h3 id="九四-随有获-贞凶。有孚-在道-以明-何咎-象曰-随有获-其义凶也。有孚在道-明功也。" tabindex="-1">九四，随有获，贞凶。有孚，在道，以明，何咎？ 象曰：随有获，其义凶也。有孚在道，明功也。 <a class="header-anchor" href="#九四-随有获-贞凶。有孚-在道-以明-何咎-象曰-随有获-其义凶也。有孚在道-明功也。" aria-label="Permalink to “九四，随有获，贞凶。有孚，在道，以明，何咎？ 象曰：随有获，其义凶也。有孚在道，明功也。”">​</a></h3><p>九四以阳刚之才，处臣位之极，若于随有获，则虽正亦凶。有获，谓得天下之心随于己。为臣之道，当使恩威一出于上，众心皆随于君。若人心从己，危疑之道也，故凶。居此地者奈何？唯孚诚积于中，动为合于道，以明哲处之，则又何咎？古之人有行之者，伊尹、周公、孔明是也，皆德及于民，而民随之。其得民之随，所以成其君之功，致其国之安，其至诚存乎中，是有孚也；其所施为无不中道，在道也；唯其明哲，故能如是以明也，复何过咎之有？是以下信而上不疑，位极而无逼上之嫌，势重而无专强之过。非圣人大贤，则不能也。其次如唐之郭子仪，威震主而主不疑，亦由中有诚孚而处无甚失也，非明哲能如是乎？</p><p>居近君之位而有获，其义固凶。能有孚而在道，则无咎，盖明哲之功也。</p><h3 id="九五-孚于嘉-吉。-象曰-孚于嘉吉-位正中也。" tabindex="-1">九五，孚于嘉，吉。 象曰：孚于嘉吉，位正中也。 <a class="header-anchor" href="#九五-孚于嘉-吉。-象曰-孚于嘉吉-位正中也。" aria-label="Permalink to “九五，孚于嘉，吉。 象曰：孚于嘉吉，位正中也。”">​</a></h3><p>九五居尊得正而中实，是其中诚在于随善，其吉可知。嘉，善也。自人君至于庶人，随道之吉，唯在随善而已。下应二之正中，为随善之义。</p><p>处正中之位，由正中之道，孚诚所随者正中也，所谓嘉也，其吉可知。所孚之嘉，谓六二也。随以得中为善，随之所防者过也，盖心所说随，则不知其过矣。</p><h3 id="上六-拘系之-乃从维之-王用亨于西山。-象曰-拘系之-上穷也。" tabindex="-1">上六，拘系之，乃从维之，王用亨于西山。 象曰：拘系之，上穷也。 <a class="header-anchor" href="#上六-拘系之-乃从维之-王用亨于西山。-象曰-拘系之-上穷也。" aria-label="Permalink to “上六，拘系之，乃从维之，王用亨于西山。 象曰：拘系之，上穷也。”">​</a></h3><p>上六以柔顺而居随之极，极乎随者也。拘系之，谓随之极，如拘持縻系之。乃从维之，又从而维系之也，谓随之固结如此。王用亨于西山，随之极如是。昔者太王用此道，亨王业于西山。太王避狄之难，去豳来岐，豳人老稚扶携以随之如归市，盖其人心之随，固结如此，用此故能亨盛其王业于西山。西山，岐山也。周之王业，盖兴于此。上居随极，固为大过，然在得民之随，与随善之固，如此乃为善也，施于他则过矣。</p><p>蛊卦</p><p>导读</p><p>《蛊》，《序卦》：“以喜随人者必有事，故受之以蛊。”承二卦之义以为次也。夫喜悦以随于人者，必有事也。无事，则何喜，何随？蛊所以次随也。蛊，事也。蛊非训事，蛊乃有事也。为卦，山下有风，风在山下，遇山而回则物乱，是为蛊象。蛊之义，坏乱也。在文为虫皿，皿之有虫，蛊坏之义。《左氏传》云：“风落山，女惑男。”以长女下于少男，乱其情也。风遇山而回，物皆挠乱，是为有事之象，故云蛊者事也。既蛊而治之，亦事也。以卦之象言之，所以成蛊也；以卦之才言之，所以治蛊也。</p><h3 id="卦辞-元-亨-利涉大川。先甲三日-后甲三日。" tabindex="-1">卦辞：元，亨，利涉大川。先甲三日，后甲三日。 <a class="header-anchor" href="#卦辞-元-亨-利涉大川。先甲三日-后甲三日。" aria-label="Permalink to “卦辞：元，亨，利涉大川。先甲三日，后甲三日。”">​</a></h3><p>既蛊则有复治之理。自古治必因乱，乱则开治，理自然也。如卦之才以治蛊，则能致元亨也。蛊之大者，济时之艰难险阻也，故曰利涉大川。</p><p>甲，数之首，事之始也，如辰之甲乙。甲第，甲令，皆谓首也，事之端也。治蛊之道，当思虑其先后三日，盖推原先后，为救弊可久之道。先甲谓先于此，究其所以然也。后甲谓后于此，虑其将然也。一日二日至于三日，言虑之深，推之远也。究其所以然，则知救之之道；虑其将然，则知备之之方。善救则前弊可革，善备则后利可久，此古之圣王所以新天下而垂后世也。后之治蛊者，不明圣人先甲后甲之诫，虑浅而事近，故劳于救世而乱不革，功未及成而弊已生矣。甲者事之首，庚者变更之首。制作政教之类，则云甲，举其首也。发号施令之事，则云庚，庚犹更也，有所更变也。</p><h3 id="《彖》曰-蛊-刚上而柔下-巽而止-蛊。蛊元亨而天下治也。利涉大川-往有事也。先甲三日-后甲三日-终则有始-天行也。" tabindex="-1">《彖》曰：蛊，刚上而柔下，巽而止，蛊。蛊元亨而天下治也。利涉大川，往有事也。先甲三日，后甲三日，终则有始，天行也。 <a class="header-anchor" href="#《彖》曰-蛊-刚上而柔下-巽而止-蛊。蛊元亨而天下治也。利涉大川-往有事也。先甲三日-后甲三日-终则有始-天行也。" aria-label="Permalink to “《彖》曰：蛊，刚上而柔下，巽而止，蛊。蛊元亨而天下治也。利涉大川，往有事也。先甲三日，后甲三日，终则有始，天行也。”">​</a></h3><p>以卦变及二体之义而言。刚上而柔下，谓乾之初九上而为上九，坤之上六下而为初六也。阳刚，尊而在上者也，今往居于上；阴柔，卑而在下者也，今来居于下。男虽少而居上，女虽长而在下，尊卑得正，上下顺理，治蛊之道也。由刚之上，柔之下，变而为艮巽。艮，止也。巽，顺也。下巽而上止，止于巽顺也。以巽顺之道治蛊，是以元亨也。</p><p>治蛊之道，如卦之才，则元亨而天下治矣。夫治乱者，苟能使尊卑上下之义正，在下者巽顺，在上者能止齐安定之，事皆止于顺，则何蛊之不治也？其道大善而亨也，如此则天下治矣。</p><p>方天下坏乱之际，宜涉艰险以往而济之，是往有所事也。</p><p>夫有始则必有终，既终则必有始，天之道也。圣人知终始之道，故能原始而究其所以然，要终而备其将然，先甲后甲而为之虑，所以能治蛊而致元亨也。</p>',102)])])}const f=e(i,[["render",l]]);export{b as __pageData,f as default};
